"""Lockfile parsers, run over lockfiles generated by the real tools (uv, npm, pnpm) and
hand-checked samples of formats whose tool is not installed here (see fixtures/lock/README)."""

from __future__ import annotations

from pathlib import Path

import pytest

from license_mcp import lockfiles as lf
from license_mcp.errors import LicenseError

from .conftest import FIXTURES, write

MAP = {
    "uv": "uv/uv.lock",
    "npm3": "npm3/package-lock.json",
    "npm2": "npm2/package-lock.json",
    "pnpm9": "pnpm9/pnpm-lock.yaml",
    "pnpm6": "pnpm6/pnpm-lock.yaml",
    "poetry": "poetry/poetry.lock",
    "yarn": "yarn/yarn.lock",
    "cargo": "cargo/Cargo.lock",
    "go": "go/go.sum",
    "requirements": "requirements/requirements.txt",
}


def load(name: str) -> dict[tuple[str, str], lf.LockedPkg]:
    lock = lf.parse(str(FIXTURES / MAP[name]))
    return {(p.name, p.version): p for p in lock.packages}


def direct_names(name: str) -> set[str]:
    return {p.name for p in load(name).values() if p.direct}


def test_uv_lock_real() -> None:
    pk = load("uv")
    names = {n for n, _ in pk}
    assert {"python-dateutil", "six", "packaging", "idna", "tzdata"} <= names
    assert direct_names("uv") == {"python-dateutil", "packaging", "idna"}
    assert all(p.ecosystem == lf.PYPI for p in pk.values())


@pytest.mark.parametrize("which", ["npm3", "npm2"])
def test_package_lock_v3_and_v2_real(which: str) -> None:
    pk = load(which)
    assert set(pk) == {("debug", "4.4.3"), ("ms", "2.1.3"), ("semver", "7.8.6"), ("is-number", "7.0.0")} or \
        {n for n, _ in pk} == {"debug", "ms", "semver", "is-number"}
    # npm records the license inside the lockfile
    assert {p.name: p.embedded_license for p in pk.values()}["semver"] == "ISC"
    assert {p.name: p.embedded_license for p in pk.values()}["ms"] == "MIT"
    assert direct_names(which) == {"debug", "semver", "is-number"}
    assert pk[next(k for k in pk if k[0] == "ms")].locations == ("node_modules/ms",)


def test_package_lock_v1_is_rejected_with_advice(tmp_path: Path) -> None:
    write(tmp_path / "package-lock.json", '{"lockfileVersion": 1, "dependencies": {}}')
    with pytest.raises(LicenseError, match="npm 7 or newer"):
        lf.parse(str(tmp_path / "package-lock.json"))


def test_package_lock_license_shapes(tmp_path: Path) -> None:
    write(tmp_path / "package-lock.json", """{
      "lockfileVersion": 3,
      "packages": {
        "": {"dependencies": {"a": "1", "b": "1", "c": "1", "d": "1"}},
        "node_modules/a": {"version": "1.0.0", "license": {"type": "MIT", "url": "x"}},
        "node_modules/b": {"version": "1.0.0", "license": ["MIT", "Apache-2.0"]},
        "node_modules/c": {"version": "1.0.0"},
        "node_modules/d": {"version": "1.0.0", "link": true},
        "node_modules/x/node_modules/e": {"name": "e", "version": "2.0.0", "license": "ISC"}
      }}""")
    pk = load_path(tmp_path / "package-lock.json")
    assert pk["a"].embedded_license == "MIT"
    assert pk["b"].embedded_license == "MIT OR Apache-2.0"
    assert pk["c"].embedded_license is None
    assert "d" not in pk
    assert pk["e"].direct is False and pk["e"].locations == ("node_modules/x/node_modules/e",)


def load_path(p: Path) -> dict[str, lf.LockedPkg]:
    return {x.name: x for x in lf.parse(str(p)).packages}


@pytest.mark.parametrize("which", ["pnpm9", "pnpm6"])
def test_pnpm_lock(which: str) -> None:
    pk = load(which)
    if which == "pnpm9":
        assert {n for n, _ in pk} == {"debug", "ms", "semver", "is-number"}
        assert direct_names(which) == {"debug", "semver", "is-number"}
    else:
        assert ("@babel/core", "7.0.0") in pk
        assert direct_names(which) == {"@babel/core", "lodash", "mkdirp"}
        loc = pk[("@babel/core", "7.0.0")].locations[0]
        assert loc == "node_modules/.pnpm/@babel+core@7.0.0/node_modules/@babel/core"


def test_pnpm_old_version_rejected(tmp_path: Path) -> None:
    write(tmp_path / "pnpm-lock.yaml", "lockfileVersion: 5.4\n\npackages:\n")
    with pytest.raises(LicenseError, match="older than 6.0"):
        lf.parse(str(tmp_path / "pnpm-lock.yaml"))


def test_pnpm_garbage_yaml_is_a_clean_error(tmp_path: Path) -> None:
    write(tmp_path / "pnpm-lock.yaml", "lockfileVersion: '9.0'\npackages:\n  this is not: a: valid: key\n  ???\n")
    with pytest.raises(LicenseError):
        lf.parse(str(tmp_path / "pnpm-lock.yaml"))


def test_poetry_lock_directs_from_pyproject() -> None:
    assert direct_names("poetry") == {"pytest", "requests"}


def test_poetry_without_pyproject_says_direct_unknown(tmp_path: Path) -> None:
    write(tmp_path / "poetry.lock", '[[package]]\nname = "a"\nversion = "1.0"\n')
    lock = lf.parse(str(tmp_path / "poetry.lock"))
    assert not lock.direct_known and lock.packages[0].direct is None
    assert any("direct vs transitive is unknown" in n for n in lock.notes)


def test_yarn_lock_v1() -> None:
    pk = load("yarn")
    assert ("lodash", "4.17.15") in pk and ("lodash", "4.18.1") in pk
    assert direct_names("yarn") == {"@babel/core", "lodash", "mkdirp"}


def test_yarn_berry_rejected(tmp_path: Path) -> None:
    write(tmp_path / "yarn.lock", '__metadata:\n  version: 6\n\n"a@npm:1":\n  version: 1.0.0\n')
    with pytest.raises(LicenseError, match="Yarn Berry"):
        lf.parse(str(tmp_path / "yarn.lock"))


def test_cargo_lock_skips_workspace_and_git() -> None:
    lock = lf.parse(str(FIXTURES / "cargo/Cargo.lock"))
    names = {p.name for p in lock.packages}
    assert "demo" not in names and "local-helper" not in names
    assert {"chrono", "smallvec", "num-traits"} <= names
    assert {p.name for p in lock.packages if p.direct} == {"chrono", "smallvec", "num-traits"}
    assert all(p.source and "crates.io" in p.source for p in lock.packages)


def test_go_sum_uses_go_mod_for_direct() -> None:
    pk = load("go")
    assert direct_names("go") == {"github.com/gin-gonic/gin"}
    assert all(p.ecosystem == lf.GO for p in pk.values())


def test_go_sum_without_go_mod(tmp_path: Path) -> None:
    write(tmp_path / "go.sum", "example.com/a v1.0.0 h1:abc=\nexample.com/a v1.0.0/go.mod h1:def=\n")
    lock = lf.parse(str(tmp_path / "go.sum"))
    assert [p.name for p in lock.packages] == ["example.com/a"]
    assert not lock.direct_known


def test_requirements_pins_and_skips() -> None:
    pk = load("requirements")
    assert set(pk) == {("jinja2", "2.10"), ("pyyaml", "5.3"), ("requests", "2.19.1")}


def test_requirements_edge_cases(tmp_path: Path) -> None:
    write(tmp_path / "requirements.txt",
          "# comment\n"
          "Flask_Login[extras]==0.6.3 ; python_version >= '3.8'  # trailing\n"
          "pkg==1.0 \\\n    --hash=sha256:abc \\\n    --hash=sha256:def\n"
          "wild==1.*\n"
          "ranged>=1.0\n"
          "git+https://example.com/x.git#egg=x\n"
          "-e .\n"
          "name @ https://example.com/a.whl\n")
    lock = lf.parse(str(tmp_path / "requirements.txt"))
    assert {(p.name, p.version) for p in lock.packages} == {("flask-login", "0.6.3"), ("pkg", "1.0")}
    assert any("not pinned" in n for n in lock.notes)


def test_detect_finds_nested_lockfiles_and_skips_vendored_dirs(tmp_path: Path) -> None:
    write(tmp_path / "uv.lock", "")
    write(tmp_path / "web" / "package-lock.json", "{}")
    write(tmp_path / "web" / "node_modules" / "x" / "package-lock.json", "{}")
    write(tmp_path / ".venv" / "Lib" / "site-packages" / "requirements.txt", "")
    write(tmp_path / "requirements-dev.txt", "")
    found = sorted(Path(p).relative_to(tmp_path).as_posix() for p in lf.detect(str(tmp_path)))
    assert found == ["requirements-dev.txt", "uv.lock", "web/package-lock.json"]


def test_detect_errors_are_actionable(tmp_path: Path) -> None:
    with pytest.raises(LicenseError, match="no lockfile found"):
        lf.detect(str(tmp_path))
    with pytest.raises(LicenseError, match="does not exist"):
        lf.detect(str(tmp_path / "nope"))
    write(tmp_path / "notes.txt", "x")
    with pytest.raises(LicenseError, match="not a supported lockfile"):
        lf.detect(str(tmp_path / "notes.txt"))


def test_malformed_files_raise_license_error_not_tracebacks(tmp_path: Path) -> None:
    cases = {
        "uv.lock": "this = is [not toml",
        "poetry.lock": "[[package]]\nname = 'x'\n",  # missing version
        "package-lock.json": "{not json",
        "Cargo.lock": "[[package]]\nname = 'a'\nsource = 'registry+x'\n",
    }
    for name, body in cases.items():
        write(tmp_path / name, body)
        with pytest.raises(LicenseError):
            lf.parse(str(tmp_path / name))


def test_deeply_nested_json_is_a_clean_error(tmp_path: Path) -> None:
    write(tmp_path / "package-lock.json", "[" * 200000 + "]" * 200000)
    with pytest.raises(LicenseError):
        lf.parse(str(tmp_path / "package-lock.json"))


def test_non_utf8_lockfile(tmp_path: Path) -> None:
    (tmp_path / "go.sum").write_bytes(b"\xff\xfe\x00garbage")
    with pytest.raises(LicenseError, match="UTF-8"):
        lf.parse(str(tmp_path / "go.sum"))


def test_lockfile_size_cap(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    write(tmp_path / "go.sum", "a v1 h1:x\n" * 10)
    monkeypatch.setattr(lf, "MAX_LOCKFILE_BYTES", 20)
    with pytest.raises(LicenseError, match="limit"):
        lf.parse(str(tmp_path / "go.sum"))
